"""Layer 15 MLP down_proj, component 1927 (one rank-one piece of it).

What it does, in plain words: almost all the time this component sits at a small
slightly negative level. It rises when the text says something is unnecessary,
unimportant or acceptable, most of all right after a negation ("no need", "not
necessary", "no problem", "doesn't matter", "not wrong"), and on plain acceptability
words ("okay", "fine", "acceptable"). It dips when the text is concessive or narrows a
point: "not even", "not just", "even if / even though", "despite", "regardless of".

The program: a baseline level plus a few keyword rules over the last few tokens of the
same document. It reads only the text so far.
"""

BASE = -0.024  # the component's typical level, its mean over text
SCALE = 1.0  # multiplies the keyword bumps below

NEGATIONS = {"not", "no", "never", "nothing", "nor", "n't", "'t", "’t"}
DISMISS = {"need", "needed", "needs", "necessary", "required", "require", "problem",
           "issue", "matter", "mind", "wrong", "bad", "important", "reason", "worry"}
ACCEPT = {"okay", "ok", "fine", "acceptable", "allowed", "possible"}
SCALAR = {"even", "just", "only", "merely", "all", "always"}
CONCESSIVE = {"despite", "regardless", "notwithstanding", "though", "although"}

READS = ()


def word(s):
    return s.strip().lower()


def bump(words, docs):
    """The keyword bump for the newest token, given the tokens before it."""
    w = words[-1]
    back = []  # earlier tokens of the same document, nearest first
    for j in range(2, len(words) + 1):
        if docs[-j] != docs[-1]:
            break
        back.append(words[-j])
    prev = back[0] if back else ""
    negated = any(x in NEGATIONS for x in back[:3])
    if w in DISMISS and negated:
        return 1.5
    if w in ACCEPT:
        return 0.6
    if w == "even":
        return -0.5 if prev in NEGATIONS else 0.2
    if w in SCALAR and prev in NEGATIONS:
        return -0.5
    if prev == "even" or w in CONCESSIVE:
        return -0.3
    return 0.0


def step(carry, prefix, upstream):
    words = [word(s) for s in prefix.token_strings[-4:]]
    docs = prefix.document_ids[-4:]
    return carry, BASE + SCALE * bump(words, docs)

"""Layer-15 MLP hidden unit 1935 (the component's main readout), as far as simple token
classes can describe it.

The unit is mostly noise-like across ordinary text, but it leans positive on Python/Java-style
member access: the word `self` itself, attribute names written with a leading dot
(`.event`, `.game`), and member or scope operators (`->`, `::`, `._`, `.get`, `_{`).
This program predicts those class means and 0 for every other token.
"""

import re

READS: tuple[str, ...] = ()

MEAN_BY_CLASS = {"self": 1.4, "attribute": 0.35, "operator": 0.8}
OPERATORS = {"->", "::", "._", ".get", "_{"}
ATTRIBUTE = re.compile(r"\.[A-Za-z_][A-Za-z0-9_]*")


def token_class(text: str) -> str | None:
    core = text.strip()
    if core == "self":
        return "self"
    if core in OPERATORS:
        return "operator"
    if ATTRIBUTE.fullmatch(core):
        return "attribute"
    return None


def step(carry, prefix, upstream):
    cls = token_class(prefix.token_strings[-1])
    return carry, MEAN_BY_CLASS.get(cls, 0.0)

"""Layer 15 MLP hidden unit 1939, the component's direction is almost entirely this unit.

What the unit does, in readable terms: it dips negative on the opening word of a greeting or
formal opener ("Hello", "Hi", "Welcome", "Dear", "Thank you", "I hope"), most strongly at the
start of a line. It also dips negative on section-heading words ("Introduction", "BACKGROUND",
"Field", "INVENTION"), on indentation after a line number in a listing, and on the first token
of a source file (#include, <?php). Most of its swings come from context these few rules do not
capture, so the rules explain well under one percent of its variance on held-out text. Its
effect on the model's predictions is correspondingly small.

Predicted value: a small baseline, plus the rules above, plus a small dip at the second token of
a document.
"""
from collections.abc import Mapping

READS: tuple[str, ...] = ()

GREETINGS = {
    "Hello", "Hi", "Hey", "Welcome", "Greetings", "Dear", "Thank", "Thanks",
    "Good", "Okay", "OK", "sorry", "hope", "apologize",
}
HEADINGS = {
    "Introduction", "INTRODUCTION", "INVENTION", "BACKGROUND", "Background",
    "Field", "FIELD", "SUMMARY", "Summary", "Abstract", "ABSTRACT",
}
CODE_OPENERS = {"#include", "<?php", "<?", "package", "import", "use"}


def step(carry, prefix, upstream: Mapping):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        pos = 0  # first token of a document
    else:
        pos = carry[1] + 1
    text = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    word = text.strip()
    at_line_start = pos > 0 and "\n" in prev
    value = -0.055  # baseline: the unit's typical small negative mean
    if word in GREETINGS:
        value -= 4.0 if at_line_start else 1.2
    if word in HEADINGS:
        value -= 1.3
    if text.isspace() and "\t" in text:
        value -= 0.35 if prev.strip().isdigit() else 0.08
    if text.isspace() and at_line_start:
        value -= 0.17
    if word in CODE_OPENERS:
        value -= 0.36
    if pos == 1:
        value -= 0.18
    return (doc, pos), value

"""Layer 15 MLP down-projection, component 1951: a negative bump where the text opens
a non-restrictive clause or an appositive.

In running prose the component goes clearly negative on the token that starts an
aside that adds information about the noun just named:
  - the relative pronoun after a comma, as in "..., which", "..., who", "..., where"
    (the strongest: about -4 for "which" and "who");
  - the comma, parenthesis or dash that follows a name or noun phrase and introduces
    an apposition, as in "Paul Offit, a pediatrician" or "Daniel Mariner, who ...".
Ordinary commas, and relative words after a preposition ("in which", "of which"),
stay near zero. Structured text (lists, code, metadata) gives nothing.

The values are the typical activations for each class, fitted by least squares on
training text, not a model of the exact computation. The class means explain only a
few percent of the variance: the component's large values depend on whether the
model expects an aside next, which a token-level rule can only approximate.

Main program: `step` looks at the newest token and the one or two before it.
"""

READS = ()

CLAUSE_OPENERS = {",", "),", '",', "–", "—"}
"""Tokens after which a relative pronoun begins a non-restrictive clause."""

WH_AFTER_COMMA = {"which": -3.9, "who": -4.5, "where": -2.0}
"""Relative word right after a comma: its typical activation."""

WH_OTHER = {"which": -1.4, "who": -0.7, "where": -0.5}
"""Relative word anywhere else, as in "in which" or "those who"."""


def is_name_word(token):
    """A word starting with a capital letter, as in names and titles."""
    word = token.strip()
    return word[:1].isupper() and word.isalpha()


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    tok = tokens[-1].strip()
    prev = tokens[-2] if len(tokens) > 1 else ""
    prev2 = tokens[-3] if len(tokens) > 2 else ""
    after_comma = prev.strip() in CLAUSE_OPENERS
    cap1 = is_name_word(prev)
    cap2 = cap1 and is_name_word(prev2)

    if tok in WH_AFTER_COMMA:
        value = WH_AFTER_COMMA[tok] if after_comma else WH_OTHER.get(tok, 0.0)
    elif tok in WH_OTHER:
        value = WH_OTHER[tok]
    elif tok == ",":
        value = -1.4 if cap2 else (-0.5 if cap1 else -0.3)
    elif tok in ("(", "（"):
        value = -0.8 if cap1 else -0.45
    elif tok == "),":
        value = -0.6
    elif tok in ("–", "—"):
        value = -0.4
    else:
        value = 0.0
    return carry, float(value)

"""Predict the component's typical activation for each kind of token.

Layer 15 MLP feature 1974 is a dense, near-Gaussian signal with no sharp trigger.
Its mean activation differs only slightly between kinds of token: mid-word pieces
(no leading space) are a little below plain words, and the first token of a row is
always about 0. This program predicts a per-kind mean, which explains almost none of
the variance (held-out R^2 about 0.001); it is the honest simple account.
"""

import re

READS = ()

FIRST_TOKEN = 0.0


def kind(s):
    core = s.strip()
    if not core:
        return "space"
    if s[:1] == " ":
        return "word"  # leading space: a new word
    if re.fullmatch(r"[A-Za-z]+", core):
        return "word_piece"  # letters with no leading space: mid-word piece
    if re.fullmatch(r"[0-9]+", core):
        return "digits"
    return "other"


MEANS = {"space": 0.036, "word": 0.041, "word_piece": 0.022, "digits": 0.044, "other": 0.045}


def step(carry, prefix, upstream):
    if len(prefix.token_ids) == 1:
        return carry, FIRST_TOKEN
    return carry, MEANS[kind(prefix.token_strings[-1])]
